MAX_ROUNDS = 3

def fake_generator(task: str, feedback: list[str]) -> str:
    """Stands in for the drafting model. It fixes whatever the critic reported."""
    draft = "Dear tenant, the lift at Block C is out of service."
    if any("date" in f for f in feedback):
        draft += " It will be repaired by 14 October."
    if any("contact" in f for f in feedback):
        draft += " Questions: facilities@harbourview.example."
    return draft

def critic(draft: str) -> list[str]:
    """Cheap checks against written criteria. A second model could judge tone."""
    problems = []
    if "October" not in draft:
        problems.append("missing repair date")
    if "@" not in draft:
        problems.append("missing contact address")
    if len(draft.split()) > 60:
        problems.append("too long: keep under 60 words")
    return problems

def evaluator_optimizer(task: str):
    feedback, best, last_count = [], None, None
    for round_no in range(1, MAX_ROUNDS + 1):
        draft = fake_generator(task, feedback)
        problems = critic(draft)
        print(f"round {round_no}: {len(problems)} problems {problems}")
        if best is None or len(problems) < best[1]:
            best = (draft, len(problems))
        if not problems:
            return draft                                  # passes every check: stop
        if last_count is not None and len(problems) >= last_count:
            break                                         # no progress: stop polishing
        feedback, last_count = problems, len(problems)
    return best[0] + "  [needs human review]"

print(evaluator_optimizer("Notice about the Block C lift"))

# Output:
# round 1: 2 problems ['missing repair date', 'missing contact address']
# round 2: 0 problems []
# Dear tenant, the lift at Block C is out of service. It will be repaired by 14 October. Questions: facilities@harbourview.example.

