import json
from pydantic import BaseModel

class Step(BaseModel):
    tool: str
    args: dict

class Plan(BaseModel):
    steps: list[Step]

ALLOWED = {"get_invoice", "get_router_swap", "explain_fee"}   # this agent's tools only
MAX_REPLANS = 2

def fake_planner(task: str, done: list, error: str | None) -> str:
    """Stands in for a model call that returns a JSON plan."""
    if error is None:
        return json.dumps({"steps": [
            {"tool": "get_invoice", "args": {"customer": "55012", "month": "2026-08"}},
            {"tool": "get_router_swap", "args": {"customer": "55012"}},
            {"tool": "explain_fee", "args": {"fee_code": "EQ-SWAP"}}]})
    # replan: the swap log was down, so use the fee code on the invoice instead
    return json.dumps({"steps": [{"tool": "explain_fee", "args": {"fee_code": "EQ-SWAP"}}]})

def run_tool(step: Step) -> str:
    if step.tool == "get_router_swap":
        raise RuntimeError("swap log service unavailable")
    return f"{step.tool} ok"

def execute(task: str) -> list[str]:
    done, error = [], None
    for attempt in range(MAX_REPLANS + 1):
        plan = Plan.model_validate_json(fake_planner(task, done, error))  # structured, checked
        bad = [s.tool for s in plan.steps if s.tool not in ALLOWED]
        if bad:
            return done + [f"rejected plan: tools not allowed {bad}"]
        for step in plan.steps:
            try:
                done.append(run_tool(step))
            except RuntimeError as e:
                error = f"step {step.tool} failed: {e}"
                done.append(error)
                break                      # stop this plan and ask for a new one
        else:
            return done                    # every step succeeded
    return done + ["gave up after replanning; handing to a person"]

for line in execute("Explain why customer 55012's bill doubled"):
    print(line)

# Output:
# get_invoice ok
# step get_router_swap failed: swap log service unavailable
# explain_fee ok

class Budget:
    def __init__(self, max_tokens=200_000, max_turns=20, max_workers=6):
        self.tokens_left = max_tokens
        self.turns_left = max_turns
        self.workers_left = max_workers

    def charge(self, resp):
        self.tokens_left -= resp.usage.input_tokens + resp.usage.output_tokens
        self.turns_left -= 1
        if self.tokens_left <= 0 or self.turns_left <= 0:
            raise BudgetExceeded("stop and return partial result")

    def spawn_worker(self):
        if self.workers_left == 0:
            raise BudgetExceeded("too many subagents")
        self.workers_left -= 1

