def quarantined_extract(email_text):
    """Stand-in for a model with NO tools. It may only return this small shape."""
    return {"date": "2026-10-12", "pallets": 8, "dock": "D4"}   # real code: call a model, then validate

def validate(form):
    assert set(form) == {"date", "pallets", "dock"}
    assert isinstance(form["pallets"], int) and 0 < form["pallets"] <= 40
    assert form["dock"] in {"D1", "D2", "D3", "D4"}          # fixed list, no free text
    return form

def run_plan(email_text):
    plan = [("book_slot", "form")]                          # fixed plan, written by trusted code
    form = validate(quarantined_extract(email_text))
    for tool, arg in plan:
        assert tool in TRUSTED_TOOLS                        # untrusted text cannot add steps
        print("calling", tool, form)

