from dataclasses import dataclass, field

READ_TOOLS = {"get_order", "track_shipment"}
WRITE_TOOLS = {"issue_refund"}
REFUND_LIMIT = 50                                   # euros; above this a supervisor decides

@dataclass
class Order:
    id: str
    customer_id: str
    total: float

@dataclass
class User:
    id: str
    visible_customers: set = field(default_factory=set)

ORDERS = {"A1": Order("A1", "c1", 240.0)}
PENDING, AUDIT = [], []

def run_tool_call(name, args, user):
    if name not in READ_TOOLS | WRITE_TOOLS:            # 1) allowlist first
        return {"error": f"tool {name} is not allowed"}
    order = ORDERS.get(args.get("order_id"))            # 2) only now read the arguments
    if order is None:
        return {"error": "unknown order"}
    if order.customer_id not in user.visible_customers: # 3) the user's own rights
        return {"error": "not permitted"}
    if name in READ_TOOLS:
        return {"status": "ok", "order": order.id, "total": order.total}
    amount = args.get("amount", 0)                       # 4) write tool
    if amount <= 0 or amount > order.total:
        return {"error": "bad refund amount"}
    if amount <= REFUND_LIMIT:                           # small refunds run at once
        AUDIT.append((user.id, name, args, "executed"))
        return {"status": "refunded", "amount": amount}
    PENDING.append((user.id, name, args))                # big refunds wait for a human
    AUDIT.append((user.id, name, args, "pending"))
    return {"status": "pending_approval", "ticket": len(PENDING)}

